        )
        configure()
        LaunchStartupTrace.shared.mark(
            .workspaceConfigured,
            recordsDiagnosticEvent: false
        )
    }

    init(
        frame frameRect: NSRect = .zero,
        launchPlan: ProjectLaunchPlan
    ) {
        self.launchPlan = launchPlan
        super.init(frame: frameRect)
        LaunchStartupTrace.shared.mark(
            .workspacePropertiesInitialized,
            recordsDiagnosticEvent: false
        )
